/* ------------------------------------------------------------------ */
/* 照片墙:微信表情包贴纸 × 拍立得木相框,挂在房间后墙                    */
/* ------------------------------------------------------------------ */
(async () => {
  const waitForWorld = () =>
    globalThis.__world
      ? Promise.resolve(globalThis.__world)
      : new Promise((resolve) => {
          const timer = setInterval(() => {
            if (globalThis.__world) { clearInterval(timer); resolve(globalThis.__world); }
          }, 200);
        });
  try {
    const world = await waitForWorld();
    const captions = ["飞行员帽", "厨师帽", "彩虹爆炸头", "橘子皮", "爆炸头红帽", "鲷鱼烧",
                      "卷发筒", "垃圾袋", "蓝色头盔", "西瓜皮", "毛巾面膜", "大蝴蝶结"];
    const loadImg = (src) => new Promise((res, rej) => {
      const im = new Image();
      im.onload = () => res(im);
      im.onerror = () => rej(new Error("load fail " + src));
      im.src = src;
    });
    const makeArt = async (idx) => {
      const img = await loadImg("./photos/" + String(idx + 1).padStart(2, "0") + ".png");
      const S = 256, CH = 36;                       // 相纸 256×292(含底部小字区)
      const cv = document.createElement("canvas");
      cv.width = S; cv.height = S + CH;
      const ctx = cv.getContext("2d");
      ctx.fillStyle = "#faf4e4";                    // 米色拍立得相纸
      ctx.fillRect(0, 0, cv.width, cv.height);
      ctx.strokeStyle = "rgba(120,100,60,.14)";
      ctx.lineWidth = 2;
      ctx.strokeRect(6, 6, S - 12, S - 12);
      const m = Math.max(img.width, img.height);
      const sc = (S - 46) / m;
      const w = img.width * sc, h = img.height * sc;
      ctx.drawImage(img, (S - w) / 2, (S - 32 - h) / 2 + 8, w, h);
      ctx.fillStyle = "#96907a";
      ctx.font = "italic 15px Georgia, 'PingFang SC', sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(captions[idx], S / 2, S + 23);
      const tex = new __T.CanvasTexture(cv);
      tex.colorSpace = __T.SRGBColorSpace;
      tex.anisotropy = 4;
      return tex;
    };
    const woodMat = new __T.MeshStandardMaterial({ color: "#dfbd8d", roughness: 0.72 });
    const wallGroup = new __T.Group();
    wallGroup.name = "photo-wall";
    const W = 0.485, H = 0.552;                     // 相框尺寸(米)
    const artGeo = new __T.PlaneGeometry(W, H);
    const frameGeo = new __T.BoxGeometry(W + 0.05, H + 0.05, 0.03);
    for (let i = 0; i < 12; i++) {
      const tex = await makeArt(i);
      const row = Math.floor(i / 6), col = i % 6;
      const x = 0.82 + col * 0.86 + row * 0.25;     // 第二行错位,更自然
      const y = row === 0 ? 1.28 : 2.04;
      const g = new __T.Group();
      g.position.set(x, y, -4.71);                  // 后墙墙面上
      g.rotation.z = ((i % 3) - 1) * 0.035;         // 轻微歪斜的手工感
      const frame = new __T.Mesh(frameGeo, woodMat);
      frame.castShadow = true;
      const art = new __T.Mesh(artGeo, new __T.MeshStandardMaterial({ map: tex, roughness: 0.9 }));
      art.position.z = 0.016;
      g.add(frame, art);
      wallGroup.add(g);
    }
    world.scene.add(wallGroup);
    // 跟随后墙可见性(相机转到背面时同步隐藏)
    const room = world.room;
    const origSetView = room.setView.bind(room);
    room.setView = (v) => { origSetView(v); wallGroup.visible = v.z > -0.04; };
    console.log("[photo-wall] 12 张表情包已上墙");
  } catch (err) {
    console.warn("[photo-wall] 挂载失败:", err?.message || err);
  }
})();
